/// <reference types="next" />
/// <reference types="next/image-types/global" />

// NOTE: This file should not be edited
// see https://nextjs.org/docs/app/building-your-application/configuring/typescript for more information.

import type { Metadata } from "next";
import "./globals.css";

export const metadata: Metadata = {
  title: "Aurora Studio — Design practice, Lisbon",
  description:
    "Aurora Studio is a four-person design practice in Lisbon building identities, interfaces and printed matter for independent businesses.",
};

export default function RootLayout({
  children,
}: Readonly<{ children: React.ReactNode }>) {
  return (
    <html lang="en">
      <body>{children}</body>
    </html>
  );
}

/* ── Aurora Studio — warm monochrome editorial system ─────────────────────── */

:root {
  --canvas: #f7f6f3;
  --surface: #ffffff;
  --ink: #111111;
  --ink-soft: #2f3437;
  --muted: #787774;
  --line: #eaeaea;
  --accent-red: #9f2f2d;
  --accent-blue: #1f6c9f;
  --accent-green: #346538;
  --accent-yellow: #956400;
  --font-sans: "Helvetica Neue", "Switzer", "SF Pro Display", Arial, sans-serif;
  --font-serif: "Newsreader", "Instrument Serif", "Playfair Display", Georgia, serif;
  --font-mono: "SF Mono", "Geist Mono", "JetBrains Mono", "Cascadia Mono", monospace;
}

* { box-sizing: border-box; margin: 0; padding: 0; }

html { scroll-behavior: smooth; }

body {
  background: var(--canvas);
  color: var(--ink);
  font-family: var(--font-sans);
  font-size: 1rem;
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
  text-rendering: optimizeLegibility;
}

h1, h2 {
  font-family: var(--font-serif);
  letter-spacing: -0.03em;
  line-height: 1.1;
}

h3 { letter-spacing: -0.01em; line-height: 1.3; }

a { color: inherit; text-decoration: none; }

.wrap { max-width: 68rem; margin: 0 auto; padding: 0 1.5rem; }

/* Accessible focus everywhere */
:where(a, button, [tabindex]):focus-visible {
  outline: 2px solid var(--ink);
  outline-offset: 3px;
  border-radius: 2px;
}

/* Visible label alternative: .skip */
.skip-link {
  position: absolute;
  left: -9999px;
  top: 0;
  background: var(--surface);
  color: var(--ink);
  padding: 0.75rem 1rem;
  z-index: 100;
  border: 1px solid var(--line);
}
.skip-link:focus { left: 1rem; top: 1rem; }

/* ── Header ──────────────────────────────────────────────────────────────── */
.site-header {
  position: fixed;
  inset: 0 0 auto 0;
  z-index: 50;
  background: rgba(247, 246, 243, 0.86);
  backdrop-filter: blur(8px);
  border-bottom: 1px solid var(--line);
}
.header-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 1rem;
  height: 4rem;
}
.brand { display: inline-flex; align-items: center; gap: 0.65rem; font-weight: 550; }
.brand-mark { width: 22px; height: 22px; display: block; }
.brand-name { font-size: 0.95rem; letter-spacing: -0.01em; }

.nav-toggle {
  display: none;
  border: 1px solid var(--line);
  background: var(--surface);
  border-radius: 6px;
  padding: 0.45rem 0.55rem;
  cursor: pointer;
  color: var(--ink);
}
.nav-toggle:active { transform: scale(0.98); }
.nav-toggle .icon-open { display: block; }
.nav-toggle .icon-close { display: none; }
.nav-toggle[aria-expanded="true"] .icon-open { display: none; }
.nav-toggle[aria-expanded="true"] .icon-close { display: block; }
.nav-toggle .icon-svg { display: block; }

.nav-links {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  list-style: none;
}
.nav-link {
  padding: 0.5rem 0.85rem;
  border-radius: 6px;
  font-size: 0.92rem;
  color: var(--ink-soft);
}
.nav-link:hover { background: rgba(17, 17, 17, 0.05); }
.nav-cta {
  margin-left: 0.35rem;
  background: var(--ink);
  color: #fff;
  padding: 0.55rem 1rem;
  border-radius: 6px;
  font-size: 0.92rem;
}
.nav-cta:hover { background: #333; }
.nav-cta:active { transform: scale(0.98); }

/* ── Hero ────────────────────────────────────────────────────────────────── */
.hero { padding: 10rem 0 6.5rem; position: relative; overflow: hidden; }
.hero-ambient {
  position: fixed;
  inset: auto -10% 30% auto;
  width: 46rem;
  height: 46rem;
  margin-left: -14rem;
  background: radial-gradient(closest-side, rgba(159, 131, 96, 0.055), transparent);
  pointer-events: none;
  z-index: -1;
}
.hero-typography { max-width: 46rem; }
.hero-kicker {
  display: inline-flex;
  align-items: center;
  gap: 0.5rem;
  background: #edf3ec;
  color: var(--accent-green);
  border-radius: 9999px;
  padding: 0.3rem 0.85rem;
  font-size: 0.72rem;
  font-weight: 600;
  letter-spacing: 0.07em;
  text-transform: uppercase;
}
.hero-kicker-dot { width: 6px; height: 6px; border-radius: 50%; background: currentColor; }
.hero-title { font-size: clamp(2.6rem, 6.2vw, 4.2rem); margin: 1.4rem 0 1.5rem; }
.hero-sub {
  max-width: 34rem;
  color: var(--muted);
  font-size: 1.08rem;
  margin-bottom: 2.2rem;
}
.hero-actions { display: flex; gap: 0.8rem; flex-wrap: wrap; align-items: center; }

.btn-primary {
  display: inline-block;
  background: var(--ink);
  color: #fff;
  padding: 0.78rem 1.4rem;
  border-radius: 6px;
  font-weight: 500;
  font-size: 0.95rem;
}
.btn-primary:hover { background: #333; }
.btn-primary:active { transform: scale(0.98); }
.btn-ghost {
  display: inline-block;
  border: 1px solid var(--line);
  background: transparent;
  color: var(--ink);
  padding: 0.78rem 1.3rem;
  border-radius: 6px;
  font-size: 0.95rem;
}
.btn-ghost:hover { background: rgba(17, 17, 17, 0.04); }

/* ── Shared section rhythm ───────────────────────────────────────────────── */
.section { padding: 5.5rem 0; }
.section + .section { border-top: 1px solid var(--line); }
section[id] { scroll-margin-top: 5rem; }
.section-head { max-width: 40rem; margin-bottom: 2.5rem; }
.section-eyebrow {
  font-family: var(--font-mono);
  font-size: 0.75rem;
  letter-spacing: 0.09em;
  text-transform: uppercase;
  color: var(--muted);
}
.section-title { font-size: clamp(1.7rem, 3.4vw, 2.3rem); margin: 0.7rem 0 0.6rem; }
.section-sub { color: var(--muted); }

/* ── Features — asymmetric bento ─────────────────────────────────────────── */
.bento {
  display: grid;
  gap: 1.1rem;
  grid-template-columns: repeat(6, 1fr);
}
.bento-note { grid-column: span 3; }
.bento-main { grid-column: span 3; grid-row: span 2; }
.bento-aux { grid-column: span 3; }
.card {
  border: 1px solid var(--line);
  border-radius: 12px;
  background: var(--surface);
  padding: clamp(1.6rem, 3vw, 2.4rem);
  display: flex;
