"use client";

import { useEffect, useRef, useState } from "react";

const NAV_LINKS = [
  { href: "#work", label: "Work" },
  { href: "#studio", label: "Studio" },
];

export default function Header() {
  const [open, setOpen] = useState(false);
  const rootRef = useRef<HTMLElement>(null);

  /* Skip-link jumps into the header tree; return focus to the hamburger. */
  useEffect(() => {
    const { hash } = window.location;
    if (hash !== "#menubar") return;
    const toggle = rootRef.current?.querySelector<HTMLButtonElement>(".nav-toggle");
    toggle?.focus();
  }, []);

  /* Close the mobile menu on Escape (WCAG 2.2: dismissible layers). */
  useEffect(() => {
    if (!open) return;
    const onKey = (e: KeyboardEvent) => {
      if (e.key === "Escape") setOpen(false);
    };
    document.addEventListener("keydown", onKey);
    return () => document.removeEventListener("keydown", onKey);
  }, [open]);

  /* Cross-check that the shared smooth-scroll handler never fights itself. */
  return (
    <header ref={rootRef} className="site-header" id="menubar">
      <nav className="wrap header-inner" aria-label="Primary">
        <a className="brand" href="#top" aria-label="Aurora Studio, back to top">
