          </svg>
          <span className="brand-name">Aurora Studio</span>
        </a>

        <button
          type="button"
          className="nav-toggle"
          aria-expanded={open}
          aria-controls="primary-menu"
          aria-label={open ? "Close menu" : "Open menu"}
          onClick={() => setOpen((v) => !v)}
        >
          <svg className="icon-svg icon-open" width="18" height="18" viewBox="0 0 24 24" aria-hidden="true">
            <path d="M4 8h16M4 16h16" stroke="currentColor" strokeWidth="1.8" strokeLinecap="round" />
          </svg>
          <svg className="icon-svg icon-close" width="18" height="18" viewBox="0 0 24 24" aria-hidden="true">
            <path d="M6 6l12 12M18 6L6 18" stroke="currentColor" strokeWidth="1.8" strokeLinecap="round" />
          </svg>
        </button>

        <div className="site-nav" id="primary-menu">
          <ul className="nav-links">
            {NAV_LINKS.map((l) => (
              <li key={l.href}>
                <a className="nav-link" href={l.href} onClick={() => setOpen(false)}>
                  {l.label}
                </a>
              </li>
            ))}
            <li>
              <a className="nav-cta" href="#contact" onClick={() => setOpen(false)}>
                Start a project
              </a>
            </li>
          </ul>
        </div>
      </nav>
    </header>
  );
}

const FEATURES = [
