              className={`card reveal ${["bento-note", "bento-main", "bento-aux"][i]}`}
              style={{ "--stagger": i + 1 } as React.CSSProperties}
            >
              <span className="card-tag">{f.tag}</span>
              <span className="card-icon" aria-hidden="true">
                <svg className="icon-svg" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.8" strokeLinecap="round" strokeLinejoin="round">
                  {i === 0 && <><circle cx="8" cy="10" r="4" /><circle cx="16" cy="10" r="4" opacity="0.45" /><path d="M3 19c1.6-2 3.6-3 5-3s3.4 1 5 3" /></>}
                  {i === 1 && <><rect x="3" y="4" width="18" height="14" rx="2" /><path d="M3 9h18M8 4v5" /></>}
                  {i === 2 && <><path d="M4 5h12a2 2 0 0 1 2 2v12H6a2 2 0 0 1-2-2V5z" /><path d="M8 9h8M8 13h8M8 17h5" /></>}
