/* Aurora Studio — nav enhancements (the site's single JavaScript file).
   Progressive enhancement only: without this file the page still works via
   CSS scroll-behavior; with it, we honour prefers-reduced-motion explicitly
   and close the mobile menu before scrolling. No dependencies, no build. */
(function () {
  "use strict";

  var prefersReduced = window.matchMedia(
    "(prefers-reduced-motion: reduce)"
  ).matches;

  /* CTA + nav smooth scroll: close the mobile drawer, then scroll. */
  document.addEventListener("click", function (event) {
    var link = event.target.closest('a[href^="#"]');
    if (!link) return;
    var id = link.getAttribute("href");
    if (!id || id === "#") return;
    var target = document.querySelector(id);
    if (!target) return;
    event.preventDefault();
    var menu = link.closest(".site-nav");
    if (menu && menu.querySelector(".nav-link.is-open")) {
      menu.querySelector(".nav-link.is-open").click();
    }
    var toggle = document.querySelector(".nav-toggle");
    if (menu && toggle && toggle.getAttribute("aria-expanded") === "true") {
      toggle.click();
    }
    target.scrollIntoView({ behavior: prefersReduced ? "auto" : "smooth" });
    /* Keep the address bar in sync without adding a second history entry. */
    if (window.history && typeof history.replaceState === "function") {
      history.replaceState(null, "", id);
    }
  });

  /* Reveal-on-scroll: translateY(12px) + opacity, staggered 80ms per item. */
  var reveals = Array.prototype.slice.call(document.querySelectorAll(".reveal"));
  if (prefersReduced || !("IntersectionObserver" in window)) {
    reveals.forEach(function (el) {
      el.classList.add("is-visible");
    });
    return;
  }
  var observer = new IntersectionObserver(
    function (entries) {
      entries.forEach(function (entry) {
        if (entry.isIntersecting) {
          entry.target.classList.add("is-visible");
          observer.unobserve(entry.target);
        }
      });
    },
    { rootMargin: "0px 0px -8% 0px", threshold: 0.05 }
  );
  reveals.forEach(function (el) {
    observer.observe(el);
  });
})();

